# 1. Create a fresh project
echo '{"name":"eslint-jsx-keyspacing-bug","private":true}' > package.json
npm install --save-dev eslint babel-eslint eslint-plugin-react react-icons react react-dom

# 2. Add a minimal ESLint configuration
cat > .eslintrc.js << 'EOF'
module.exports = {
  parser: 'babel-eslint',
  plugins: ['react'],
  rules: {
    'key-spacing': ['warn', { multiLine: { align: 'value' } }],
    'object-curly-newline': ['warn', { multiline: true, minProperties: 5 }],
    'object-property-newline': ['warn', { allowAllPropertiesOnSameLine: true }],
    'object-curly-spacing': ['warn', 'always', { arraysInObjects: false, objectsInObjects: false }],
  },
  settings: { react: { version: 'detect' } },
};
EOF

# 3. Create a React component with an inline style object
mkdir src && cat > src/App.jsx << 'EOF'
import React from 'react';
import { Fa } from 'react-icons/fa';

export default function App() {
  return (
    <div>
      <Fa
        icon="lock"
        style={{ marginRight: '4px', color: '#0C090A', opacity: '0.6', fontSize: '18px', verticalAlign: 'middle' }}
      />
    </div>
  );
}
EOF

# 4. Run ESLint’s auto–fix
npx eslint --fix src/App.jsx

# 5. Inspect the output in src/App.jsx — you will see the inline object is split and values misaligned.
